    // Fallback for Node.js environments without native fetch
    const http = require('http');
    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/metrics-ingest',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload)
      }
    };

    const req = http.request(options, (res) => {
      // Ignore response
      res.on('data', () => {});
      res.on('end', () => {});
    });

    req.on('error', () => {});
    req.write(payload);
    req.end();
  }
}

